from itertools import permutations
import sys

def distance(p1, p2):
    return min(abs(p1[0] - p2[0]), abs(p1[1] - p2[1]))

def total_distance(route, points):
    total = 0
    for i in range(len(route) - 1):
        total += distance(points[route[i]], points[route[i + 1]])
    return total

def solve_case(points):
    n = len(points)
    if n == 1:
        return [0]

    # Generate all permutations and find the one with minimal total distance
    min_dist = float('inf')
    best_perm = None

    for perm in permutations(range(n)):
        dist = total_distance(perm, points)
        if dist < min_dist:
            min_dist = dist
            best_perm = perm
        elif dist == min_dist:
            # Choose lexicographically smaller permutation
            if perm < best_perm:
                best_perm = perm

    # Compute XOR of the permutation
    xor_result = 0
    for i in best_perm:
        xor_result ^= i

    return xor_result

